/**
 * Build a standardised display-data object for an item entity.
 * Used by inventory, chest, ground-pickup and any other UI that shows item info.
 * When an item is unidentified, bonuses, affixes, description, and spell details
 * are suppressed so the UI does not reveal hidden properties.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} itemId
 * @returns {object|null}
 */
export function buildItemDisplayData(world, itemId) {
  const info = world.get(itemId, ItemInfo);
  if (!info) return null;
  const ni = world.get(itemId, NamedIdentity);

  // Determine if this item is unidentified
  const identity = ni?.identity || '';
  const needsId = requiresIdentification(info);
  const gemType = String(info?.type || "") === "gem";
  const identified = gemType
    ? (info.identified === true || (identity && isIdentified(identity)))
    : (info.identified === true || !needsId || (identity && isIdentified(identity)));

  const spellId = identified ? spellIdFromIdentity(identity) : "";
  const linkedSpell = spellId ? getSpell(spellId) : null;
  const procPackages = identified ? buildProcPackageSummaries(world, itemId) : [];
  const catalogItem = identified ? getCatalogItem(identity) : null;
  const procPackageMechanics = formatProcPackageMechanics(procPackages, catalogItem?.mechanicFormats);
  const attachedAffixIds = identified ? buildAttachedAffixIds(world, itemId) : [];
  const attachedAffixSet = new Set(attachedAffixIds);
  const authoredAffixIds = identified
    ? (Array.isArray(info.affixes) ? info.affixes : [])
      .filter((affixId) => !attachedAffixSet.has(String(affixId || '')))
    : [];
  const affixMechanics = formatAffixMechanics(authoredAffixIds, catalogItem?.mechanicFormats);
  const enchantmentMechanics = formatAffixMechanics(
    attachedAffixIds,
    catalogItem?.mechanicFormats,
    'Enchant',
    (affixId) => ENCHANT_SCROLL_ICON_BY_AFFIX.get(String(affixId || '')) || '',
  );
/**
 * @param {any} it
 * @returns {boolean}
 */
export function hasScrollForIdentify(it) {
  return !!it?.hasScrollOfIdentify;
}

/**
 * @param {any} it
 * @returns {string}
 */
export function getQuickChipPrimaryActionLabel(it) {
  const action = getQuickChipPrimaryAction(it);
  if (action === 'apply') return String(it?.type || '') === 'gem' ? 'Socket' : 'Apply';
  if (action === 'equip') return 'Equip';
  if (action === 'drink') return 'Drink';
  return 'Use';
}

/**
 * @param {any} it
 * @param {{ expanded?: boolean }} opts
 * @returns {string}
 */
export function getQuickChipDetailLine(it, opts = {}) {
  const expanded = !!opts?.expanded;
  const count = normalizePositiveCount(it?.count);
  if (expanded) return `x${count} • details open`;
  const actionable = isQuickChipActionable(it);
  if (actionable && !!it?.justPickedUp) return `x${count} • just picked up • tap for details/pin`;
  if (actionable) return `x${count} • tap for details`;
  return `x${count} • picked up`;
}

/**
 * @param {any} it
 * @returns {boolean}
 */
export function isQuickChipActionable(it) {
  const t = String(it?.type || '');
  if (t === 'equip' || t === 'ammo' || t === 'wand') return true;
  if (t === 'tool') return true;
  if (isQuickChipPotion(it) || t === 'scroll' || t === 'learn' || t === 'book' || t === 'food' || t === 'gem') return (it?.count || 0) > 0;
  return false;
}

